// UiFactory — builds UGUI + TextMeshPro UI in code (no hand-written scene data).
// All screens use these helpers, so the UI is deterministic and batchmode-safe.
// Text uses the CJK font asset (Noto Sans CJK SC, generated by Editor/BuildScript
// into Resources/Fonts/); falls back to TMP's default font if it is missing.
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.Events;
using TMPro;

namespace GalgameOnline.UI
{
    public static class UiFactory
    {
        private static TMP_FontAsset _cjkFont;
        private static bool _fontTried;

        public static TMP_FontAsset CjkFont
        {
            get
            {
                if (!_fontTried)
                {
                    _fontTried = true;
                    _cjkFont = Resources.Load<TMP_FontAsset>("Fonts/NotoSansCJKsc SDF");
                }
                return _cjkFont;
            }
        }

        public static void ApplyFont(TextMeshProUGUI tmp)
        {
            if (CjkFont != null) tmp.font = CjkFont;
        }

        public static void Stretch(RectTransform rt)
        {
            rt.anchorMin = Vector2.zero;
            rt.anchorMax = Vector2.one;
            rt.offsetMin = Vector2.zero;
            rt.offsetMax = Vector2.zero;
        }

        public static GameObject Panel(Transform parent, string name,
            Vector2 anchorMin, Vector2 anchorMax, Vector2 size, Color bg)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var rt = go.AddComponent<RectTransform>();
            rt.anchorMin = anchorMin;
            rt.anchorMax = anchorMax;
            rt.sizeDelta = size;
            var img = go.AddComponent<Image>();
            img.color = bg;
            return go;
        }

        public static TextMeshProUGUI Label(Transform parent, string name, string text,
            int fontSize, TextAlignmentOptions align, Color color, bool bold = false)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var tmp = go.AddComponent<TextMeshProUGUI>();
            tmp.text = text;
            tmp.fontSize = fontSize;
            tmp.alignment = align;
            tmp.color = color;
            tmp.fontStyle = bold ? FontStyles.Bold : FontStyles.Normal;
            ApplyFont(tmp);
            var rt = go.GetComponent<RectTransform>();
            rt.anchorMin = new Vector2(0, 1);
            rt.anchorMax = new Vector2(0, 1);
            rt.pivot = new Vector2(0, 1);
            rt.sizeDelta = new Vector2(600, 40);
            return tmp;
        }

        public static void Place(RectTransform rt, float x, float y, float w, float h)
        {
            rt.anchoredPosition = new Vector2(x, y);
            rt.sizeDelta = new Vector2(w, h);
        }

        public static Button Button(Transform parent, string name, string label,
            UnityAction onClick, Vector2 size, Color? bg = null)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var rt = go.AddComponent<RectTransform>();
            rt.sizeDelta = size;
            var img = go.AddComponent<Image>();
            img.color = bg ?? new Color(0.16f, 0.32f, 0.62f, 1f);
            var btn = go.AddComponent<Button>();
            btn.onClick.AddListener(onClick);
            var colors = btn.colors;
            colors.highlightedColor = new Color(0.22f, 0.42f, 0.78f, 1f);
            colors.pressedColor = new Color(0.10f, 0.22f, 0.45f, 1f);
            btn.colors = colors;

            var txt = Label(go.transform, "Text", label, 22, TextAlignmentOptions.Center, Color.white);
            Stretch(txt.rectTransform);
            return btn;
        }

        public static TMP_InputField InputField(Transform parent, string name, string placeholder,
            Vector2 size, bool isPassword = false)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var rt = go.AddComponent<RectTransform>();
            rt.sizeDelta = size;
            var img = go.AddComponent<Image>();
            img.color = new Color(1f, 1f, 1f, 0.08f);

            var input = go.AddComponent<TMP_InputField>();

            var textArea = new GameObject("Text Area");
            textArea.transform.SetParent(go.transform, false);
            var areaRt = textArea.AddComponent<RectTransform>();
            Stretch(areaRt);
            areaRt.offsetMin = new Vector2(10, 6);
            areaRt.offsetMax = new Vector2(-10, -6);
            textArea.AddComponent<RectMask2D>();

            var textGo = new GameObject("Text");
            textGo.transform.SetParent(textArea.transform, false);
            var tmp = textGo.AddComponent<TextMeshProUGUI>();
            tmp.fontSize = 22;
            tmp.color = Color.white;
            ApplyFont(tmp);
            Stretch(tmp.rectTransform);

            var phGo = new GameObject("Placeholder");
            phGo.transform.SetParent(textArea.transform, false);
            var ph = phGo.AddComponent<TextMeshProUGUI>();
            ph.text = placeholder;
            ph.fontSize = 22;
            ph.color = new Color(1f, 1f, 1f, 0.45f);
            ApplyFont(ph);
            Stretch(ph.rectTransform);

            input.textViewport = areaRt;
            input.textComponent = tmp;
            input.placeholder = ph;
            input.contentType = isPassword ? TMP_InputField.ContentType.Password
                                           : TMP_InputField.ContentType.Standard;
            return input;
        }

        /// <summary>Creates a vertical ScrollRect with a Content panel (VerticalLayoutGroup).</summary>
        public static (ScrollRect scroll, RectTransform content) ScrollView(Transform parent, string name,
            Vector2 anchorMin, Vector2 anchorMax, Vector2 size)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var rt = go.AddComponent<RectTransform>();
            rt.anchorMin = anchorMin;
            rt.anchorMax = anchorMax;
            rt.sizeDelta = size;
            var img = go.AddComponent<Image>();
            img.color = new Color(0f, 0f, 0f, 0.15f);
            var scroll = go.AddComponent<ScrollRect>();
            scroll.horizontal = false;

            var vp = new GameObject("Viewport");
            vp.transform.SetParent(go.transform, false);
            var vpRt = vp.AddComponent<RectTransform>();
            Stretch(vpRt);
            vp.AddComponent<Mask>();
            vp.AddComponent<Image>().color = Color.clear;
            scroll.viewport = vpRt;

            var content = new GameObject("Content");
            content.transform.SetParent(vp.transform, false);
            var cRt = content.AddComponent<RectTransform>();
            cRt.anchorMin = new Vector2(0, 1);
            cRt.anchorMax = new Vector2(1, 1);
            cRt.pivot = new Vector2(0.5f, 1);
            cRt.sizeDelta = new Vector2(0, 0);
            var layout = content.AddComponent<VerticalLayoutGroup>();
            layout.padding = new RectOffset(8, 8, 8, 8);
            layout.spacing = 8;
            layout.childControlWidth = true;
            layout.childControlHeight = false;
            layout.childForceExpandWidth = true;
            layout.childForceExpandHeight = false;
            content.AddComponent<ContentSizeFitter>().verticalFit = ContentSizeFitter.FitMode.PreferredSize;
            scroll.content = cRt;
            return (scroll, cRt);
        }

        public static void ClearChildren(Transform t)
        {
            for (int i = t.childCount - 1; i >= 0; i--)
                Object.Destroy(t.GetChild(i).gameObject);
        }

        /// <summary>Standard screen scaffold: full-screen dark background + top bar with title + back button.</summary>
        public static (GameObject root, GameObject topBar) ScreenBase(Transform canvas, string title,
            System.Action onBack)
        {
            var root = new GameObject("Screen");
            root.transform.SetParent(canvas, false);
            var rootRt = root.AddComponent<RectTransform>();
            Stretch(rootRt);
            root.AddComponent<Image>().color = new Color(0.05f, 0.06f, 0.10f, 1f);

            var top = Panel(root.transform, "TopBar",
                new Vector2(0, 1), new Vector2(1, 1), new Vector2(0, 64),
                new Color(0.10f, 0.12f, 0.20f, 1f));
            var topRt = top.GetComponent<RectTransform>();
            topRt.pivot = new Vector2(0.5f, 1);
            topRt.anchoredPosition = Vector2.zero;

            var titleLabel = Label(top.transform, "Title", title, 26,
                TextAlignmentOptions.Left, Color.white, true);
            Place(titleLabel.rectTransform, 76, -14, 700, 40);

            if (onBack != null)
            {
                var back = Button(top.transform, "BackButton", "← 返回", new UnityAction(onBack), new Vector2(110, 44));
                var bRt = back.GetComponent<RectTransform>();
                bRt.anchorMin = new Vector2(0, 0.5f);
                bRt.anchorMax = new Vector2(0, 0.5f);
                bRt.pivot = new Vector2(0, 0.5f);
                bRt.anchoredPosition = new Vector2(12, 0);
            }
            return (root, top);
        }
    }
}
